-- End-of-day snapshots per employee, generated by the end_of_day_report job; monthly scorecards read them. Additive only.
CREATE TABLE "DayScorecard" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "workDate" TEXT NOT NULL,
    "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expected" BOOLEAN NOT NULL DEFAULT true,
    "clockIn" TEXT,
    "clockOut" TEXT,
    "attendanceMinutes" INTEGER NOT NULL DEFAULT 0,
    "lateMinutes" INTEGER NOT NULL DEFAULT 0,
    "tasksDone" INTEGER NOT NULL DEFAULT 0,
    "tasksOverdue" INTEGER NOT NULL DEFAULT 0,
    "hoursLogged" DECIMAL(6,2) NOT NULL DEFAULT 0,
    "salesKind" TEXT,
    "activity" INTEGER NOT NULL DEFAULT 0,
    "target" INTEGER,
    "prospectsAdded" INTEGER NOT NULL DEFAULT 0,
    "outreach" INTEGER NOT NULL DEFAULT 0,
    "visits" INTEGER NOT NULL DEFAULT 0,
    "demosRequested" INTEGER NOT NULL DEFAULT 0,
    "reportStatus" TEXT NOT NULL DEFAULT 'MISSING',
    "rating" INTEGER,
    "score" INTEGER NOT NULL DEFAULT 0,
    "scoreParts" JSONB,

    CONSTRAINT "DayScorecard_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "DayScorecard_userId_workDate_key" ON "DayScorecard"("userId", "workDate");
CREATE INDEX "DayScorecard_organizationId_workDate_idx" ON "DayScorecard"("organizationId", "workDate");
